var builder = WebApplication.CreateBuilder(args);

// 1. Register Underlying Model Provider
IChatClient innerClient = new AzureOpenAIClient(
        new Uri(builder.Configuration["AzureOpenAI:Endpoint"]!),
        new DefaultAzureCredential())
    .AsChatClient(builder.Configuration["AzureOpenAI:DeploymentName"] ?? "gpt-4o");

// 2. Compose Microsoft.Extensions.AI Middleware Chain
builder.Services.AddChatClient(chatBuilder => chatBuilder
    .UseLogging() // Logs prompt/completion tokens
    .UseOpenTelemetry() // W3C distributed trace spans
    .UseDistributedCache() // Caches deterministic completions
    .UseFunctionInvocation() // Auto-invokes registered agent tools
    .Use(innerClient));

// 3. Register Hybrid Search & Ingestion Services
builder.Services.AddScoped<IHybridSearchService, PostgresHybridSearchService>();
builder.Services.AddScoped<IConversationRepository, ConversationRepository>();

var app = builder.Build();

app.MapPost("/api/chat/stream", async (
    [FromBody] ChatStreamRequest request,
    IChatClient chatClient,
    IHybridSearchService searchService,
    HttpContext context,
    CancellationToken cancellationToken) =>
{
    context.Response.Headers.ContentType = "text/event-stream";
    context.Response.Headers.CacheControl = "no-cache";
    context.Response.Headers.Connection = "keep-alive";

    // 1. Retrieve authorized hybrid chunks
    var chunks = await searchService.RetrieveTopChunksAsync(
        request.TenantId, 
        request.Query, 
        topK: 5, 
        cancellationToken);

    // 2. Assemble system prompt with citations
    var messages = PromptBuilder.BuildGroundedPrompt(request.History, request.Query, chunks);

    // 3. Stream completions via SSE
    await foreach (var update in chatClient.CompleteStreamingAsync(messages, cancellationToken: cancellationToken))
    {
        var ssePayload = JsonSerializer.Serialize(new
        {
            token = update.Text,
            finishReason = update.FinishReason?.ToString()
        });

        await context.Response.WriteAsync($"data: {ssePayload}\n\n", cancellationToken);
        await context.Response.Body.FlushAsync(cancellationToken);
    }

    // Signal completion
    await context.Response.WriteAsync("data: [DONE]\n\n", cancellationToken);
})
.RequireAuthorization()
.RequireRateLimiting("AiChatRateLimit");

app.MapPost("/mcp/tools/search-knowledge", async (
    [FromBody] McpToolRequest request,
    IHybridSearchService searchService,
    ClaimsPrincipal user,
    CancellationToken ct) =>
{
    var tenantId = user.GetTenantId();
    var results = await searchService.RetrieveTopChunksAsync(tenantId, request.Arguments["query"].GetString()!, 5, ct);

    return Results.Ok(new McpToolResponse
    {
        Content = [
            new { type = "text", text = JsonSerializer.Serialize(results) }
        ]
    });
})
.RequireAuthorization("McpClientPolicy");
